  ('build-your-box', 'Build Your Own Box', 'cookies', 'Mix and match any flavours in a pack of 2, 4 or 6.', 'Can’t choose just one? Pick your pack size, then fill it with any mix of our cookie flavours. Boxed and ribboned, ready to gift.', '["packaging","cookies"]'::jsonb, '[{"id":"pack2","label":"Pack of 2","servings":"2 cookies","price":10},{"id":"pack4","label":"Pack of 4","servings":"4 cookies","price":19},{"id":"pack6","label":"Pack of 6","servings":"6 cookies","price":27}]'::jsonb, '[{"label":"Classic Chocolate Chip","price":0},{"label":"Double Chocolate Fudge","price":0},{"label":"Biscoff Crumble","price":0},{"label":"Red Velvet Cheesecake","price":0},{"label":"S’mores","price":0},{"label":"Birthday Funfetti","price":0}]'::jsonb, '[]'::jsonb, false, 1, 3, 'Mix & match', true, '[{"label":"Allergens","value":"Contains wheat, eggs, dairy. Made in a kitchen that handles nuts."},{"label":"Size","value":"Each cookie is about 5 oz — thick, crisp at the edges and soft in the middle."},{"label":"Storage","value":"Keep in the box at room temperature for up to 3 days. Warm for 5 minutes at 350°F for that just-baked feel."}]'::jsonb, '#EFEEE6', 0, true, '{"es":{"name":"Arma tu caja","short":"Combina los sabores que quieras en un paquete de 2, 4 o 6.","description":"¿No puedes elegir solo una? Elige el tamaño de tu paquete y llénalo con la combinación de sabores que quieras. Va en caja y con lazo, lista para regalar.","badge":"Combina sabores","sizes":{"pack2":{"label":"Paquete de 2","servings":"2 galletas"},"pack4":{"label":"Paquete de 4","servings":"4 galletas"},"pack6":{"label":"Paquete de 6","servings":"6 galletas"}},"details":[{"label":"Alérgenos","value":"Contiene trigo, huevo y lácteos. Hecho en una cocina que maneja frutos secos."},{"label":"Tamaño","value":"Cada galleta pesa unas 5 oz — gruesa, crujiente por fuera y suave por dentro."},{"label":"Conservación","value":"Guárdalas en la caja a temperatura ambiente hasta 3 días. Caliéntalas 5 minutos a 350 °F para que sepan recién horneadas."}]}}'::jsonb),
  ('classic-chocolate-chip', 'Classic Chocolate Chip', 'cookies', 'Brown butter dough, dark chocolate chunks and flaky sea salt.', 'The one that started it all. A thick New York–style cookie made with nutty brown butter and loaded with puddles of dark and milk chocolate, finished with flaky sea salt.', '["cookies","packaging"]'::jsonb, '[{"id":"pack2","label":"Pack of 2","servings":"2 cookies","price":10},{"id":"pack4","label":"Pack of 4","servings":"4 cookies","price":19},{"id":"pack6","label":"Pack of 6","servings":"6 cookies","price":27}]'::jsonb, '[]'::jsonb, '[]'::jsonb, false, 1, 3, 'Bestseller', true, '[{"label":"Allergens","value":"Contains wheat, eggs, dairy. Made in a kitchen that handles nuts."},{"label":"Size","value":"Each cookie is about 5 oz — thick, crisp at the edges and soft in the middle."},{"label":"Storage","value":"Keep in the box at room temperature for up to 3 days. Warm for 5 minutes at 350°F for that just-baked feel."}]'::jsonb, '#F6E7E3', 1, true, '{"es":{"name":"Chispas de chocolate clásica","short":"Masa de mantequilla tostada, trozos de chocolate oscuro y sal en escamas.","description":"La que empezó todo. Una galleta gruesa estilo New York hecha con mantequilla tostada y llena de charcos de chocolate oscuro y con leche, terminada con sal en escamas.","badge":"La más vendida","sizes":{"pack2":{"label":"Paquete de 2","servings":"2 galletas"},"pack4":{"label":"Paquete de 4","servings":"4 galletas"},"pack6":{"label":"Paquete de 6","servings":"6 galletas"}},"details":[{"label":"Alérgenos","value":"Contiene trigo, huevo y lácteos. Hecho en una cocina que maneja frutos secos."},{"label":"Tamaño","value":"Cada galleta pesa unas 5 oz — gruesa, crujiente por fuera y suave por dentro."},{"label":"Conservación","value":"Guárdalas en la caja a temperatura ambiente hasta 3 días. Caliéntalas 5 minutos a 350 °F para que sepan recién horneadas."}]}}'::jsonb),
  ('double-chocolate-fudge', 'Double Chocolate Fudge', 'cookies', 'Dark cocoa dough with a molten fudge centre.', 'For serious chocolate lovers: a deep cocoa cookie studded with white and dark chocolate, hiding a soft, molten fudge centre.', '["cookies","packaging"]'::jsonb, '[{"id":"pack2","label":"Pack of 2","servings":"2 cookies","price":10},{"id":"pack4","label":"Pack of 4","servings":"4 cookies","price":19},{"id":"pack6","label":"Pack of 6","servings":"6 cookies","price":27}]'::jsonb, '[]'::jsonb, '[]'::jsonb, false, 1, 3, null, true, '[{"label":"Allergens","value":"Contains wheat, eggs, dairy. Made in a kitchen that handles nuts."},{"label":"Size","value":"Each cookie is about 5 oz — thick, crisp at the edges and soft in the middle."},{"label":"Storage","value":"Keep in the box at room temperature for up to 3 days. Warm for 5 minutes at 350°F for that just-baked feel."}]'::jsonb, '#EFEEE6', 2, true, '{"es":{"name":"Doble chocolate fudge","short":"Masa de cacao oscuro con centro de fudge fundido.","description":"Para los amantes del chocolate: una galleta de cacao intenso con chocolate blanco y oscuro, que esconde un centro suave de fudge fundido.","sizes":{"pack2":{"label":"Paquete de 2","servings":"2 galletas"},"pack4":{"label":"Paquete de 4","servings":"4 galletas"},"pack6":{"label":"Paquete de 6","servings":"6 galletas"}},"details":[{"label":"Alérgenos","value":"Contiene trigo, huevo y lácteos. Hecho en una cocina que maneja frutos secos."},{"label":"Tamaño","value":"Cada galleta pesa unas 5 oz — gruesa, crujiente por fuera y suave por dentro."},{"label":"Conservación","value":"Guárdalas en la caja a temperatura ambiente hasta 3 días. Caliéntalas 5 minutos a 350 °F para que sepan recién horneadas."}]}}'::jsonb),
  ('biscoff-crumble', 'Biscoff Crumble', 'cookies', 'Cookie-butter centre, white chocolate and Biscoff crumb.', 'A brown sugar cookie stuffed with a gooey Biscoff cookie-butter centre, topped with white chocolate and crushed Lotus biscuits.', '["cookies","packaging"]'::jsonb, '[{"id":"pack2","label":"Pack of 2","servings":"2 cookies","price":10},{"id":"pack4","label":"Pack of 4","servings":"4 cookies","price":19},{"id":"pack6","label":"Pack of 6","servings":"6 cookies","price":27}]'::jsonb, '[]'::jsonb, '[]'::jsonb, false, 1, 3, 'Fan favourite', true, '[{"label":"Allergens","value":"Contains wheat, eggs, dairy. Made in a kitchen that handles nuts."},{"label":"Size","value":"Each cookie is about 5 oz — thick, crisp at the edges and soft in the middle."},{"label":"Storage","value":"Keep in the box at room temperature for up to 3 days. Warm for 5 minutes at 350°F for that just-baked feel."}]'::jsonb, '#F6E7E3', 3, true, '{"es":{"name":"Biscoff crumble","short":"Centro de crema Biscoff, chocolate blanco y galleta Biscoff triturada.","description":"Una galleta de azúcar morena rellena de crema de galleta Biscoff, cubierta con chocolate blanco y galletas Lotus trituradas.","badge":"Favorita de los clientes","sizes":{"pack2":{"label":"Paquete de 2","servings":"2 galletas"},"pack4":{"label":"Paquete de 4","servings":"4 galletas"},"pack6":{"label":"Paquete de 6","servings":"6 galletas"}},"details":[{"label":"Alérgenos","value":"Contiene trigo, huevo y lácteos. Hecho en una cocina que maneja frutos secos."},{"label":"Tamaño","value":"Cada galleta pesa unas 5 oz — gruesa, crujiente por fuera y suave por dentro."},{"label":"Conservación","value":"Guárdalas en la caja a temperatura ambiente hasta 3 días. Caliéntalas 5 minutos a 350 °F para que sepan recién horneadas."}]}}'::jsonb),
