  ('lemon-cream-cake', 'Lemon Cream Cake', 'cakes', 'Lemon chiffon, tangy curd and soft vanilla cream.', 'Bright and elegant. Feather-light lemon chiffon layered with tangy house-made lemon curd and vanilla chantilly, finished with candied lemon and tiny edible flowers.', '["lemon","floral","vanilla"]'::jsonb, '[{"id":"6in","label":"6\" round","servings":"8–10 servings","price":66},{"id":"8in","label":"8\" round","servings":"14–18 servings","price":92},{"id":"10in","label":"10\" round","servings":"24–30 servings","price":124}]'::jsonb, '[{"label":"Lemon chiffon","price":0},{"label":"Lemon & elderflower","price":0},{"label":"Gluten-free lemon","price":8}]'::jsonb, '[{"id":"classic","label":"Classic Sweet Daisy finish","price":0},{"id":"fresh-flowers","label":"Fresh seasonal flowers","price":18},{"id":"gold-leaf","label":"Edible gold leaf accents","price":14},{"id":"berries","label":"Fresh berry crown","price":12}]'::jsonb, true, 2, 24, null, false, '[{"label":"Allergens","value":"Contains wheat, eggs, dairy. Made in a kitchen that handles nuts."},{"label":"Storage","value":"Keep refrigerated. Serve at room temperature — remove 1 hour before slicing."},{"label":"Best enjoyed","value":"Within 3 days of collection."}]'::jsonb, '#EFEEE6', 103, false, '{}'::jsonb),
  ('pistachio-rose-cake', 'Pistachio Rose Cake', 'cakes', 'Pistachio sponge, raspberry and a delicate rose buttercream.', 'Our most romantic cake. Toasted pistachio sponge layered with raspberry compote and a softly perfumed rose buttercream, scattered with crushed pistachio and dried petals.', '["pistachio","floral","wedding"]'::jsonb, '[{"id":"6in","label":"6\" round","servings":"8–10 servings","price":74},{"id":"8in","label":"8\" round","servings":"14–18 servings","price":100},{"id":"10in","label":"10\" round","servings":"24–30 servings","price":132}]'::jsonb, '[{"label":"Pistachio sponge","price":0},{"label":"Vanilla sponge","price":0}]'::jsonb, '[{"id":"classic","label":"Classic Sweet Daisy finish","price":0},{"id":"fresh-flowers","label":"Fresh seasonal flowers","price":18},{"id":"gold-leaf","label":"Edible gold leaf accents","price":14},{"id":"berries","label":"Fresh berry crown","price":12}]'::jsonb, true, 3, 30, 'New', false, '[{"label":"Allergens","value":"Contains pistachio, wheat, eggs, dairy."},{"label":"Storage","value":"Keep refrigerated. Serve at room temperature — remove 1 hour before slicing."},{"label":"Best enjoyed","value":"Within 3 days of collection."}]'::jsonb, '#F6E7E3', 104, false, '{}'::jsonb),
  ('carrot-walnut-cake', 'Carrot & Walnut Cake', 'cakes', 'Spiced carrot sponge, toasted walnuts, cream cheese frosting.', 'A classic made beautifully. Warmly spiced carrot sponge with toasted walnuts and golden raisins, layered with a tangy cream cheese frosting and finished with a semi-naked texture.', '["carrot","sliced","studio"]'::jsonb, '[{"id":"6in","label":"6\" round","servings":"8–10 servings","price":62},{"id":"8in","label":"8\" round","servings":"14–18 servings","price":88},{"id":"10in","label":"10\" round","servings":"24–30 servings","price":120}]'::jsonb, '[{"label":"Classic with walnuts","price":0},{"label":"Nut-free","price":0}]'::jsonb, '[{"id":"classic","label":"Classic Sweet Daisy finish","price":0},{"id":"fresh-flowers","label":"Fresh seasonal flowers","price":18},{"id":"gold-leaf","label":"Edible gold leaf accents","price":14},{"id":"berries","label":"Fresh berry crown","price":12}]'::jsonb, true, 2, 24, null, false, '[{"label":"Allergens","value":"Contains walnuts, wheat, eggs, dairy."},{"label":"Storage","value":"Keep refrigerated. Serve at room temperature — remove 1 hour before slicing."},{"label":"Best enjoyed","value":"Within 3 days of collection."}]'::jsonb, '#EFEEE6', 105, false, '{}'::jsonb),
