  ('bento-heart-cake', 'Bento Heart Cake', 'mini-cakes', 'A heart-shaped mini cake in a keepsake gift box.', 'A sweet little love letter. A heart-shaped vanilla or chocolate mini cake, piped in vintage style and presented in our keepsake box — perfect for anniversaries and just-because moments.', '["birthday","mini"]'::jsonb, '[{"id":"one","label":"Heart mini","servings":"1–2 servings","price":32}]'::jsonb, '[{"label":"Vanilla & raspberry","price":0},{"label":"Chocolate velvet","price":0}]'::jsonb, '[]'::jsonb, true, 1, 4, null, false, '[{"label":"Allergens","value":"Contains wheat, eggs, dairy. Made in a kitchen that handles nuts."},{"label":"Storage","value":"Keep refrigerated. Serve at room temperature — remove 1 hour before slicing."},{"label":"Best enjoyed","value":"Within 3 days of collection."}]'::jsonb, '#EFEEE6', 107, false, '{}'::jsonb),
