  ('vanilla-bean-cupcakes', 'Vanilla Bean Cupcakes', 'cupcakes', 'Classic vanilla with a swirl of silky buttercream.', 'Simple, perfect and loved by everyone. Madagascar vanilla cupcakes with a generous swirl of vanilla Swiss meringue buttercream and a sugar daisy.', '["cupcakesAlt","cupcakes"]'::jsonb, '[{"id":"box6","label":"Box of 6","servings":"6 cupcakes","price":32},{"id":"box12","label":"Box of 12","servings":"12 cupcakes","price":60}]'::jsonb, '[]'::jsonb, '[]'::jsonb, false, 1, 4, null, false, '[{"label":"Allergens","value":"Contains wheat, eggs, dairy. Made in a kitchen that handles nuts."},{"label":"Storage","value":"Keep refrigerated. Serve at room temperature — remove 1 hour before slicing."},{"label":"Best enjoyed","value":"Within 3 days of collection."}]'::jsonb, '#EFEEE6', 109, false, '{}'::jsonb),
